check_code:
syn={'Stall':'Delay'}
opts={'A':'Delay','B':'Progress','C':'Complain','D':'Surge'}
r=syn['Stall']
assert r==opts['A']
for k in 'BCD': assert r!=opts[k]

s='L M N _ O L L M _ Q O L L _ N Q O _ L M N Q _ L L M'.split()
unit='LMNQOL'
opts={'A':'QLMNO','B':'QNMLO','C':'NQLMO','D':'QMNLO'}
def fits(o):
    it=iter(o); t=[next(it) if c=='_' else c for c in s]
    return all(t[i]==unit[i%6] for i in range(len(t)))
assert [k for k,v in opts.items() if fits(v)]==['B']
